* { box-sizing: border-box; }
:root { color-scheme: dark; font-family: system-ui, sans-serif; font-size: 16px; background: #101d2a; color: #eaf3ed; }
body { min-height: 100vh; margin: 0; padding: 28px 16px; display: grid; place-items: center; background: radial-gradient(ellipse at 50% 0%, #294152 0, #101d2a 65%); }
.board-card { width: min(760px, 100%); padding: clamp(20px, 5vw, 40px); border: 2px solid #59717b; border-radius: 12px; background: #182a35; box-shadow: 0 18px 55px #07101899; }
.board-header, .board-footer { display: flex; align-items: center; justify-content: space-between; gap: 20px; }
.eyebrow, .clock-label { margin: 0; color: #86c9b1; font-size: .8rem; font-weight: 750; letter-spacing: .12em; }
h1 { margin: 6px 0 0; font-size: clamp(2rem, 7vw, 3rem); line-height: 1.05; }
.clock-box { min-width: 118px; padding: 12px 16px; border: 1px solid #59717b; border-radius: 8px; text-align: center; background: #101d2a; }
.clock-box time { display: block; margin-top: 3px; color: #f4c95d; font: 700 1.8rem/1.2 ui-monospace, SFMono-Regular, Consolas, monospace; }
.column-headings, .departure { display: grid; grid-template-columns: minmax(0, 1fr) 90px 100px; align-items: center; gap: 12px; }
.column-headings { margin-top: 34px; padding: 0 16px 10px; color: #a8b9bc; font-size: .85rem; font-weight: 700; text-transform: uppercase; letter-spacing: .06em; }
.departures { display: grid; gap: 8px; margin: 0; padding: 0; list-style: none; }
.departure { min-height: 58px; padding: 10px 16px; border: 1px solid #405963; border-radius: 7px; background: #203640; font-size: 1rem; }
.destination { font-weight: 700; }
.train-time, .platform { font-family: ui-monospace, SFMono-Regular, Consolas, monospace; font-weight: 700; }
.platform { color: #b6d7cb; }
.departure.next { border: 2px solid #f4c95d; background: #3a3b2e; box-shadow: inset 5px 0 #f4c95d; }
.departure.next .destination::after { content: '  NEXT'; color: #f4c95d; font-size: .7rem; letter-spacing: .08em; vertical-align: middle; }
.departure.departed { color: #829395; background: #19272c; opacity: .65; }
.departure.departed .platform { color: inherit; }
.board-footer { margin-top: 24px; }
.status { margin: 0; color: #b9ccc8; }
button { min-height: 48px; padding: 10px 16px; border: 2px solid #f4c95d; border-radius: 7px; background: #f4c95d; color: #172630; font: inherit; font-weight: 750; cursor: pointer; transition: transform .08s ease, background .15s ease, box-shadow .15s ease; }
button:hover { background: #ffda79; box-shadow: 0 4px 14px #f4c95d44; }
button:focus-visible { outline: 3px solid #eaf3ed; outline-offset: 3px; }
button:active { transform: translateY(2px); background: #dfb445; }
@media (max-width: 480px) {
  body { padding: 16px 10px; }
  .board-card { padding: 20px 14px; }
  .board-header, .board-footer { align-items: flex-start; }
  .column-headings, .departure { grid-template-columns: minmax(0, 1fr) 64px 76px; gap: 7px; }
  .column-headings { padding-inline: 9px; font-size: .72rem; }
  .departure { padding-inline: 9px; font-size: .9rem; }
  .departure.next .destination::after { display: block; margin-top: 3px; }
  .board-footer { flex-direction: column; }
  button { width: 100%; }
}

const trains = [
  { destination: 'Northport', time: '08:10', platform: '1' },
  { destination: 'Riverside', time: '08:20', platform: '3' },
  { destination: 'Old Town', time: '08:30', platform: '2' },
  { destination: 'Lakeside', time: '08:45', platform: '4' },
  { destination: 'Westhaven', time: '09:00', platform: '1' },
  { destination: 'Hillcrest', time: '09:15', platform: '5' }
];
let minutes = 8 * 60;
const list = document.querySelector('#departures');
const clock = document.querySelector('#clock');
const status = document.querySelector('#status');

function render() {
  const nextIndex = trains.findIndex(train => {
    const [hours, mins] = train.time.split(':').map(Number);
    return hours * 60 + mins > minutes;
  });
  clock.textContent = `${String(Math.floor(minutes / 60) % 24).padStart(2, '0')}:${String(minutes % 60).padStart(2, '0')}`;
  list.replaceChildren(...trains.map((train, index) => {
    const [hours, mins] = train.time.split(':').map(Number);
    const row = document.createElement('li');
    row.className = 'departure';
    if (hours * 60 + mins <= minutes) row.classList.add('departed');
    if (index === nextIndex) row.classList.add('next');
    row.innerHTML = `<span class="destination">${train.destination}</span><time class="train-time">${train.time}</time><span class="platform">${train.platform}</span>`;
    return row;
  }));
  status.textContent = nextIndex < 0 ? 'No more departures today' : `Next departure: ${trains[nextIndex].destination} at ${trains[nextIndex].time} · Platform ${trains[nextIndex].platform}`;
}

document.querySelector('#advance').addEventListener('click', () => {
  minutes = (minutes + 5) % (24 * 60);
  render();
});
render();
